  if(r.excludeRegime&&(x.regime||'UNKNOWN')===r.excludeRegime)return false;
  if(r.requireRegime&&(x.regime||'UNKNOWN')!==r.requireRegime)return false;
  if(r.excludeSetup&&canonicalSetup(x.setup)===canonicalSetup(r.excludeSetup))return false;
